# -*- coding: utf-8 -*-
from _lib import *
MM='Manuel des Monstres 5e (2014)'
WB='The Wild Beyond the Witchlight (2021)'
I(2,'Dans D&D 5e, lequel de ces monstres n’est pas de type « fée » ?','Treant',['Dryade','Satyre','Pixie'],'Le treant est une plante. La dryade, le satyre et la pixie sont des fées.',MM+', entrées « Treant », « Dryade », « Satyre », « Pixie »')
I(3,'Dans D&D 5e, lequel de ces monstres n’est pas de type « fée » ?','Guenaude nocturne',['Guenaude verte','Guenaude des mers','Pixie'],'La guenaude nocturne est un fiélon ; les guenaudes verte et des mers sont des fées.',MM+', entrées des guenaudes')
I(2,'Dans D&D 5e, laquelle de ces créatures ne vole pas ?','Dryade',['Pixie','Sprite','Dragon féerique'],'La dryade marche ; la pixie, le sprite et le dragon féerique ont des ailes et volent.',MM+', entrées correspondantes')
T(1,'Dans D&D 5e, la Féerie est le plan d’existence où vivent les ____.','fées',['morts-vivants','fiélons','élémentaires'],'La Féerie (Feywild) est le plan des fées, reflet lumineux et sauvage du monde matériel.',"Dungeon Master’s Guide 5e (2014), chapitre « Les plans »")
T(1,'Dans D&D 5e, le ____ joue de la flûte pour charmer, effrayer ou endormir.','satyre',['sprite','gnome','centaure'],'La flûte du satyre peut charmer, effrayer ou endormir ceux qui l’entendent.',MM+', entrée « Satyre »')
T(2,'Dans D&D 5e, un sabbat de guenaudes est formé de ____ guenaudes.','trois',['deux','quatre','cinq'],'Un sabbat réunit trois guenaudes et leur donne accès à des sorts partagés.',MM+', entrée « Guenaude »')
M(2,'Dans D&D 5e, lesquels de ces peuples sont liés à la Féerie ? (plusieurs bonnes réponses)',['Eladrin','Harengon','Fée'],['Tieffelin','Drakéide'],'Eladrins, harengons et fées sont des peuples de la Féerie ; tieffelins et drakéides ont d’autres origines.',WB+' et Mordenkainen Presents: Monsters of the Multiverse (2022)')
M(3,'Dans D&D 5e, lesquelles de ces créatures sont de type « fée » ? (plusieurs bonnes réponses)',['Guenaude verte','Guenaude des mers'],['Guenaude nocturne','Treant','Fantôme'],'Les guenaudes verte et des mers sont des fées. La nocturne est un fiélon, le treant une plante, le fantôme un mort-vivant.',MM+', entrées correspondantes')
M(3,'Dans D&D 5e, lesquelles de ces créatures peuvent devenir invisibles ? (plusieurs bonnes réponses)',['Pixie','Sprite','Dragon féerique'],['Satyre','Dryade'],'Pixie, sprite et dragon féerique peuvent se rendre invisibles ; le satyre et la dryade n’ont pas ce pouvoir.',MM+', entrées correspondantes')
O(2,'Classe ces fées par FP croissant.',['Pixie','Satyre','Dryade','Guenaude verte','Guenaude nocturne'],'FP : pixie 1/4, satyre 1/2, dryade 1, guenaude verte 3, guenaude nocturne 5.',MM+', blocs de caractéristiques')
O(3,'Classe ces publications D&D dans l’ordre chronologique de leur parution.',['Volo’s Guide to Monsters','Mordenkainen’s Tome of Foes','Tasha’s Cauldron of Everything','The Wild Beyond the Witchlight'],'2016, 2018, 2020 et 2021 : de Volo’s Guide à l’aventure dans la Féerie.','Catalogue des suppléments D&D 5e')
A(1,'Associe chaque fée à sa particularité.',[('Satyre','Flûte enchantée'),('Dryade','Lien avec un arbre'),('Chien clignotant','Téléportation'),('Sprite','Arc minuscule et vue du cœur')],'Chaque fée a un trait marquant : musique, arbre, téléportation ou petit arc.',MM+', entrées correspondantes')
A(3,'Associe chaque guenaude à son FP.',[('Guenaude des mers','FP 2'),('Guenaude verte','FP 3'),('Guenaude nocturne','FP 5')],'La guenaude des mers vaut FP 2, la verte FP 3 et la nocturne FP 5.',MM+', entrées des guenaudes')
W(1,['Je suis mi-homme, mi-bouc.','J’aime la fête, le vin et la musique.','Ma flûte peut charmer, effrayer ou endormir.'],'Satyre',['Dryade','Pixie','Sprite'],'Le satyre est la fée festive de la forêt.',MM+', entrée « Satyre »')
W(2,['Je suis une fée liée à un arbre.','Je ne peux pas m’en éloigner longtemps.','Je peux me téléporter d’un arbre vivant à un autre.'],'Dryade',['Satyre','Treant','Guenaude verte'],'La dryade est liée à son arbre et se déplace par Pas d’arbre.',MM+', entrée « Dryade »')
W(3,['Je suis minuscule et ailé.','Je porte un petit arc.','Mon toucher révèle l’état d’esprit d’une créature.'],'Sprite',['Pixie','Dryade','Satyre'],'Le sprite possède la capacité Vue du cœur et un arc minuscule.',MM+', entrée « Sprite »')
W(2,['Je ressemble à un chien intelligent à la fourrure fauve.','Je suis loyal bon.','Je disparais d’un endroit pour réapparaître ailleurs.'],'Chien clignotant',['Chien infernal','Loup arctique','Worg'],'Le chien clignotant se téléporte à volonté et défend les bons.',MM+', entrée « Chien clignotant »')
save('fees-sylvains','fee')
